"use client";

import React from "react";
import { StepIndicator } from "@/components/ui/StepIndicator";
import { useAppDispatch, useAppSelector } from "@/store/hooks";
import {
  patchDraftDoctor,
  patchDraftPatient,
  patchDraftRecipient,
  submitDraft,
} from "@/features/orders/ordersSlice";
import type {
  IDoctorFormData,
  IPatientFormData,
  IRecipientFormData,
} from "@/lib/interface";

const steps = ["Ασθενής", "Παραλήπτης", "Ιατρός", "Έλεγχος"] as const;

export default function OrderRetailWizard() {
  const dispatch = useAppDispatch();
  const draft = useAppSelector((s) => s.orders.draft);

  const patient = draft.patient;
  const recipient = draft.recipient;
  const doctor = draft.doctor;

  const [step, setStep] = React.useState(0);

  const needsRecipient = patient.pickedUpByOther;

  const effectiveSteps = React.useMemo(() => {
    return needsRecipient ? [...steps] : [steps[0], steps[2], steps[3]];
  }, [needsRecipient]);

  const maxStep = effectiveSteps.length - 1;

  function goNext() {
    setStep((s) => Math.min(s + 1, maxStep));
  }

  function goPrev() {
    setStep((s) => Math.max(s - 1, 0));
  }

  function onSave() {
    // One unified payload no matter the type.
    // If EOPYY, draft.syntagiUploaded will exist.
    dispatch(submitDraft());
    alert("Saved (demo). Draft submitted.");
  }

  const currentLabel = effectiveSteps[step];

  return (
    <div>
      <StepIndicator steps={effectiveSteps as unknown as string[]} current={step} />

      {currentLabel === "Ασθενής" ? (
        <PatientStep
          data={patient}
          onChange={(p) => dispatch(patchDraftPatient(p))}
        />
      ) : null}

      {currentLabel === "Παραλήπτης" ? (
        <RecipientStep
          data={recipient}
          onChange={(p) => dispatch(patchDraftRecipient(p))}
        />
      ) : null}

      {currentLabel === "Ιατρός" ? (
        <DoctorStep
          data={doctor}
          onChange={(p) => dispatch(patchDraftDoctor(p))}
        />
      ) : null}

      {currentLabel === "Έλεγχος" ? (
        <ReviewStep
          type={draft.type}
          syntagiUploaded={draft.syntagiUploaded}
          patient={patient}
          recipient={needsRecipient ? recipient : null}
          doctor={doctor}
        />
      ) : null}

      <div className="d-flex gap-2 mt-3">
        <button
          type="button"
          className="btn btn-outline-secondary flex-fill"
          onClick={goPrev}
          disabled={step === 0}
        >
          <i className="bi bi-chevron-left me-2" />
          Back
        </button>

        {step < maxStep ? (
          <button type="button" className="btn btn-primary flex-fill" onClick={goNext}>
            Next
            <i className="bi bi-chevron-right ms-2" />
          </button>
        ) : (
          <button type="button" className="btn btn-success flex-fill" onClick={onSave}>
            <i className="bi bi-check2-circle me-2" />
            Save
          </button>
        )}
      </div>
    </div>
  );
}

function Field({
  label,
  children,
  hint,
}: {
  label: string;
  children: React.ReactNode;
  hint?: string;
}) {
  return (
    <div className="mb-3">
      <label className="form-label fw-semibold">{label}</label>
      {children}
      {hint ? <div className="form-text">{hint}</div> : null}
    </div>
  );
}

function PatientStep({
  data,
  onChange,
}: {
  data: IPatientFormData;
  onChange: (patch: Partial<IPatientFormData>) => void;
}) {
  return (
    <div className="app-card p-4">
      <div className="fw-semibold mb-2">Στοιχεία ασθενή</div>

      <Field label="Ονοματεπώνυμο">
        <input
          className="form-control"
          value={data.fullName}
          onChange={(e) => onChange({ fullName: e.target.value })}
        />
      </Field>

      <div className="row g-2">
        <div className="col-7">
          <Field label="ΑΜΚΑ">
            <input
              className="form-control"
              inputMode="numeric"
              value={data.amka}
              onChange={(e) => onChange({ amka: e.target.value })}
            />
          </Field>
        </div>
        <div className="col-5">
          <Field label="Ημ/νία Γέννησης" hint="π.χ. 01/01/1990">
            <input
              className="form-control"
              value={data.dob}
              onChange={(e) => onChange({ dob: e.target.value })}
            />
          </Field>
        </div>
      </div>

      <div className="row g-2">
        <div className="col-7">
          <Field label="Τηλέφωνο">
            <input
              className="form-control"
              inputMode="tel"
              value={data.phone}
              onChange={(e) => onChange({ phone: e.target.value })}
            />
          </Field>
        </div>
        <div className="col-5">
          <Field label="Email">
            <input
              className="form-control"
              inputMode="email"
              value={data.email}
              onChange={(e) => onChange({ email: e.target.value })}
            />
          </Field>
        </div>
      </div>

      <Field label="Διεύθυνση">
        <input
          className="form-control"
          value={data.address}
          onChange={(e) => onChange({ address: e.target.value })}
        />
      </Field>

      <div className="row g-2">
        <div className="col-8">
          <Field label="Πόλη">
            <input
              className="form-control"
              value={data.city}
              onChange={(e) => onChange({ city: e.target.value })}
            />
          </Field>
        </div>
        <div className="col-4">
          <Field label="ΤΚ">
            <input
              className="form-control"
              inputMode="numeric"
              value={data.zip}
              onChange={(e) => onChange({ zip: e.target.value })}
            />
          </Field>
        </div>
      </div>

      <div className="app-divider my-2" />

      <div className="form-check form-switch mb-2">
        <input
          className="form-check-input"
          type="checkbox"
          checked={data.pickedUpByOther}
          onChange={(e) => onChange({ pickedUpByOther: e.target.checked })}
          id="pickedUpByOther"
        />
        <label className="form-check-label" htmlFor="pickedUpByOther">
          Παραλαβή από άλλο άτομο (εμφάνιση στοιχείων παραλήπτη)
        </label>
      </div>
    </div>
  );
}

